const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

const validationRules = {
    fullName: {
        validate: (value) => value.trim().length > 0,
        message: 'Full name is required'
    },
    email: {
        validate: (value) => {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailRegex.test(value);
        },
        message: 'Please enter a valid email address'
    },
    phone: {
        validate: (value) => {
            if (value.trim() === '') return true;
            const phoneRegex = /^[\d\s()+-]+$|^\+1[-.\s]?\d{3}[-.\s]?\d{3}[-.\s]?\d{4}$|^\(\d{3}\)\s?\d{3}[-.]?\d{4}$/;
            return phoneRegex.test(value);
        },
        message: 'Please enter a valid phone number'
    }
};

function showError(input, message) {
    input.classList.add('error');
    const errorSpan = input.parentElement.querySelector('.error-message');
    errorSpan.textContent = message;
}

function clearError(input) {
    input.classList.remove('error');
    const errorSpan = input.parentElement.querySelector('.error-message');
    errorSpan.textContent = '';
}

function validateField(fieldName, input) {
    const value = input.value;
    const rules = validationRules[fieldName];

    if (!rules.validate(value)) {
        showError(input, rules.message);
        return false;
    }

    clearError(input);
    return true;
}

fullNameInput.addEventListener('blur', () => validateField('fullName', fullNameInput));
emailInput.addEventListener('blur', () => validateField('email', emailInput));
phoneInput.addEventListener('blur', () => validateField('phone', phoneInput));

fullNameInput.addEventListener('input', () => {
    if (fullNameInput.classList.contains('error')) {
        validateField('fullName', fullNameInput);
    }
});

emailInput.addEventListener('input', () => {
    if (emailInput.classList.contains('error')) {
        validateField('email', emailInput);
    }
});

phoneInput.addEventListener('input', () => {
    if (phoneInput.classList.contains('error')) {
        validateField('phone', phoneInput);
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    const fullNameValid = validateField('fullName', fullNameInput);
    const emailValid = validateField('email', emailInput);
    const phoneValid = validateField('phone', phoneInput);

    if (fullNameValid && emailValid && phoneValid) {
        form.style.display = 'none';
        successMessage.style.display = 'block';

        setTimeout(() => {
            form.reset();
            form.style.display = 'block';
            successMessage.style.display = 'none';
            fullNameInput.focus();
        }, 3000);
    }
});
